#include <stdio.h>
#include <string.h>
#include <ctype.h>

static int soundex_digit(char c) {
    switch (c) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T': return 3;
        case 'L': return 4;
        case 'M': case 'N': return 5;
        case 'R': return 6;
        default: return 0;
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2 || argv[1][0] == '\0') {
        puts("EMPTY");
        return 0;
    }

    const char *input = argv[1];
    char code[5]; // 4 chars + null terminator
    // first character (uppercase) stays as is
    code[0] = (char)toupper((unsigned char)input[0]);
    int count = 1; // number of characters placed in code
    int prev = soundex_digit(code[0]);

    for (size_t i = 1; input[i] != '\0' && count < 4; ++i) {
        char ch = (char)toupper((unsigned char)input[i]);
        int digit = soundex_digit(ch);
        if (digit == 0) {
            continue; // ignore vowels and other non‑coded letters
        }
        if (digit == prev) {
            continue; // suppress duplicate codes
        }
        code[count++] = (char)('0' + digit);
        prev = digit;
    }
    // pad with zeros if needed
    while (count < 4) {
        code[count++] = '0';
    }
    code[4] = '\0';
    puts(code);
    return 0;
}
}
